import numpy as np
t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
full=[(i,j) for i in range(4) for j in range(5)]
gs={'log t':np.log(t),'sqrt t':np.sqrt(t),'1/t':1/t,'exp(-t)':np.exp(-t),'exp(t/12)':np.exp(t/12),'1/(1+t)':1/(1+t),'t^3':t**3,'exp(-t/3)':np.exp(-t/3),'exp(-0.5t)':np.exp(-0.5*t),'sin(t/2)':np.sin(t/2),'cos(t/2)':np.cos(t/2),'t^1.5':t**1.5}
res=[]
for name,g in gs.items():
    for mode in ['add','mulP']:
        if mode=='add':
            cols=[t**i*P**j for i,j in full]+[g]
        else:
            cols=[t**i*P**j for i,j in full]+[g*P,g*P**2,g*P**3]
        A=np.column_stack(cols); c,_,_,_=np.linalg.lstsq(A,y,rcond=None)
        res.append((np.mean((y-A@c)**2)/np.var(y),name,mode))
for r_ in sorted(res)[:8]: print(r_)
